#include <mrs/tone_library.hpp>
#include <mrs/audio.hpp>
#include <algorithm>
#include <iomanip>
#include <set>
#include <sstream>
#include <cmath>
#include <map>

namespace mrs::audio {
namespace {
void require(bool ok,const char* why){if(!ok)throw std::invalid_argument(why);}
std::string utf8(const std::filesystem::path& p){auto s=p.generic_u8string();return {s.begin(),s.end()};}
std::filesystem::path path(const std::string& s){return std::filesystem::path(std::u8string(s.begin(),s.end()));}
void text(const std::string& s,std::size_t max=4096){require(s.size()<=max&&s.find('\0')==std::string::npos,"Tone library text exceeds limits");}
std::string read(std::istream& in){std::string s;in>>std::quoted(s);require(static_cast<bool>(in),"Truncated tone library");text(s,32768);return s;}
std::size_t count(std::istream& in,std::size_t max){std::size_t n{};in>>n;require(static_cast<bool>(in)&&n<=max,"Tone library count exceeds limits");return n;}
std::string tag(const CabAsset& a,const char* key){auto it=a.mapping.tags.find(key);return it==a.mapping.tags.end()?std::string{}:it->second;}
void family(ToneModel& m,const std::string& amp){
    if(amp.empty()||!m.family.empty())return;
    m.family="family:"+std::to_string(static_cast<int>(m.kind))+":"+m.role+":"+std::to_string(m.maker.size())+":"+m.maker+amp;
    m.family_title=m.maker.empty()?amp:m.maker+" "+amp;
}
SourceAsset asset(const CabManifest& m,const CabAsset& a){SourceAsset s;s.id=a.id;s.root=utf8(m.root);s.file={a.relative,utf8(m.root/path(a.relative)),a.digest,a.bytes};s.rate=a.rate;s.channels=a.channels;s.frames=a.frames;return s;}
}
std::string tone_family(const ToneModel& m){return m.family.empty()?m.id:m.family;}
std::vector<const ToneModel*> tone_variants(const ToneLibrary& library,const ToneModel& model){
    std::vector<const ToneModel*> result;
    for(const auto& m:library.models)if(tone_family(m)==tone_family(model))result.push_back(&m);
    return result;
}
void ToneLibrary::validate() const {
    require(models.size()<=1000&&sources.size()<=8000,"Tone library exceeds model/source budget");
    std::set<std::string> assetIds,modelIds,defaults; std::map<std::string,std::pair<ToneKind,std::string>> families;
    for(const auto& s:sources){text(s.id,256);require(!s.id.empty()&&assetIds.insert(s.id).second,"Duplicate/empty source identity");text(s.root,32768);text(s.file.relative);text(s.file.absolute,32768);text(s.file.digest,256);require(!s.file.digest.empty()&&s.file.bytes>0&&s.file.bytes<=64*1024*1024,"Missing source fingerprint");const auto rel=path(s.file.relative);require(!rel.empty()&&!rel.is_absolute()&&!rel.has_root_name(),"Invalid relative source path");for(const auto& part:rel)require(part!="..","Unsafe relative source path");require(path(s.root).is_absolute()&&path(s.file.absolute).is_absolute(),"Source bookmark needs absolute root/fallback");require(s.rate>=8000&&s.rate<=192000&&(s.channels==1||s.channels==2)&&s.frames>0&&s.frames<=s.rate,"Unsupported WAV model format");}
    for(const auto& m:models){text(m.id,256);text(m.title,256);require(!m.id.empty()&&!m.title.empty()&&modelIds.insert(m.id).second,"Duplicate/empty model identity");text(m.family,1024);text(m.family_title,256);require(m.family.empty()==m.family_title.empty(),"Incomplete model family");if(!m.family.empty()){auto [it,added]=families.emplace(m.family,std::pair{m.kind,m.role});require(added||it->second==std::pair{m.kind,m.role},"Inconsistent model family backend/role");}if(m.preferred)require(defaults.insert(tone_family(m)).second,"Multiple preferred IRs in one model");text(m.maker,256);text(m.variant,256);text(m.provenance,256);text(m.notes);text(m.artwork,32768);text(m.artwork_rights,1024);require(m.kind==ToneKind::wav_ir||m.kind==ToneKind::nam,"Invalid model kind");require(m.role=="unknown"||(m.kind==ToneKind::wav_ir&&(m.role=="full_combo"||m.role=="cabinet_only"))||(m.kind==ToneKind::nam&&(m.role=="full_rig"||m.role=="amp_only")),"Role belongs to a different backend");require(m.artwork.empty()||(!m.artwork_rights.empty()&&path(m.artwork).is_absolute()),"Artwork needs a local path and rights note");require(m.tags.size()<=32&&m.sources.size()<=16,"Model tags/variants exceed budget");for(const auto& t:m.tags)text(t,128);require(m.kind!=ToneKind::wav_ir||!m.sources.empty(),"WAV model has no source");std::set<std::string> used;const SourceAsset* first{};for(const auto& id:m.sources){require(assetIds.contains(id)&&used.insert(id).second,"Missing/duplicate source reference");const auto& s=*std::find_if(sources.begin(),sources.end(),[&](const auto& v){return v.id==id;});if(!first)first=&s;else require(first->channels==s.channels&&std::abs(1000.*first->frames/first->rate-1000.*s.frames/s.rate)<.1,"Model alternatives must keep capture length/channel layout");}}
}
std::string serialize_tone_library(const ToneLibrary& lib){lib.validate();std::ostringstream o;o<<"MRS_TONE_LIBRARY 2 "<<lib.sources.size()<<' '<<lib.models.size()<<'\n';for(const auto& s:lib.sources)o<<std::quoted(s.id)<<' '<<std::quoted(s.root)<<' '<<std::quoted(s.file.relative)<<' '<<std::quoted(s.file.absolute)<<' '<<std::quoted(s.file.digest)<<' '<<s.file.bytes<<' '<<s.rate<<' '<<s.channels<<' '<<s.frames<<'\n';for(const auto& m:lib.models){o<<std::quoted(m.id)<<' '<<std::quoted(m.title)<<' '<<std::quoted(m.maker)<<' '<<std::quoted(m.variant)<<' '<<static_cast<int>(m.kind)<<' '<<std::quoted(m.role)<<' '<<std::quoted(m.provenance)<<' '<<m.favorite<<' '<<std::quoted(m.artwork)<<' '<<std::quoted(m.artwork_rights)<<' '<<std::quoted(m.notes)<<' '<<m.sources.size();for(const auto& id:m.sources)o<<' '<<std::quoted(id);o<<' '<<m.tags.size();for(const auto& t:m.tags)o<<' '<<std::quoted(t);o<<' '<<std::quoted(m.family)<<' '<<std::quoted(m.family_title)<<' '<<m.preferred<<'\n';}auto result=o.str();require(result.size()<=16*1024*1024,"Tone library exceeds byte budget");return result;}
ToneLibrary deserialize_tone_library(std::string_view bytes){require(bytes.size()<=16*1024*1024,"Tone library exceeds byte budget");std::istringstream in{std::string(bytes)};std::string magic;unsigned version{};in>>magic>>version;require(magic=="MRS_TONE_LIBRARY"&&(version==1||version==2),"Unsupported tone library");auto ns=count(in,8000),nm=count(in,1000);ToneLibrary out;for(std::size_t i=0;i<ns;++i){SourceAsset s;s.id=read(in);s.root=read(in);s.file.relative=read(in);s.file.absolute=read(in);s.file.digest=read(in);in>>s.file.bytes>>s.rate>>s.channels>>s.frames;out.sources.push_back(std::move(s));}for(std::size_t i=0;i<nm;++i){ToneModel m;m.id=read(in);m.title=read(in);m.maker=read(in);m.variant=read(in);int kind{},favorite{};in>>kind;m.kind=static_cast<ToneKind>(kind);m.role=read(in);m.provenance=read(in);in>>favorite;require(favorite==0||favorite==1,"Invalid favorite flag");m.favorite=favorite!=0;m.artwork=read(in);m.artwork_rights=read(in);m.notes=read(in);auto n=count(in,16);for(std::size_t j=0;j<n;++j)m.sources.push_back(read(in));n=count(in,32);for(std::size_t j=0;j<n;++j)m.tags.push_back(read(in));if(version>=2){m.family=read(in);m.family_title=read(in);int preferred{};in>>preferred;require(static_cast<bool>(in)&&(preferred==0||preferred==1),"Invalid preferred IR flag");m.preferred=preferred!=0;}else{const auto suffix=" / "+m.variant;if(!m.variant.empty()&&m.title.size()>suffix.size()&&m.title.ends_with(suffix))family(m,m.title.substr(0,m.title.size()-suffix.size()));}out.models.push_back(std::move(m));}in>>std::ws;require(in.eof(),"Trailing tone library data");out.validate();return out;}
void curate_cab_manifest(ToneLibrary& lib,const CabManifest& manifest){auto candidate=lib;for(const auto& a:manifest.assets){if(!a.present||!a.error.empty())continue;auto s=asset(manifest,a);for(const auto& existing:candidate.sources)if(existing.file.absolute==s.file.absolute&&existing.file.digest==s.file.digest&&existing.file.bytes==s.file.bytes){s.id=existing.id;break;}auto found=std::find_if(candidate.sources.begin(),candidate.sources.end(),[&](const auto& v){return v.id==s.id;});if(found==candidate.sources.end())candidate.sources.push_back(s);else if(found->file.digest==s.file.digest&&found->file.bytes==s.file.bytes)*found=s;else continue; // changed file requires explicit new import
        const auto modelId="tone:"+a.variant_id+":"+std::to_string(a.channels)+":"+std::to_string(static_cast<unsigned long long>(std::llround(a.duration_ms())));
        auto model=std::find_if(candidate.models.begin(),candidate.models.end(),[&](const auto& m){return m.id==modelId;});if(model==candidate.models.end()){auto existing=std::find_if(candidate.models.begin(),candidate.models.end(),[&](const auto& m){return std::find(m.sources.begin(),m.sources.end(),s.id)!=m.sources.end();});if(existing!=candidate.models.end()){family(*existing,tag(a,"amp_model"));continue;}ToneModel m;m.id=modelId;m.variant=tag(a,"capture_variant");if(m.variant.empty())m.variant=utf8(path(a.relative).stem());const auto amp=tag(a,"amp_model");m.maker=tag(a,"amp_make");m.title=amp.empty()?m.variant:amp+" / "+m.variant;m.role=cab_ir_role(a.mapping);if(m.role=="cabinet")m.role="cabinet_only";m.provenance=a.mapping.source=="manual"?"userAssigned":a.mapping.classified?a.mapping.source+" / "+a.mapping.confidence:"unclassified";m.notes=tag(a,"capture_notes");family(m,amp);m.sources={s.id};candidate.models.push_back(std::move(m));}else {family(*model,tag(a,"amp_model"));if(std::find(model->sources.begin(),model->sources.end(),s.id)==model->sources.end())model->sources.push_back(s.id);}
    }candidate.validate();lib=std::move(candidate);}
const SourceAsset* tone_source(const ToneLibrary& lib,const ToneModel& m,std::uint32_t rate){const SourceAsset* chosen{};for(const auto& id:m.sources){const auto it=std::find_if(lib.sources.begin(),lib.sources.end(),[&](const auto& s){return s.id==id;});if(it==lib.sources.end())continue;if(it->rate==rate)return &*it;if(!chosen||(it->rate==48000&&chosen->rate!=48000))chosen=&*it;}return chosen;}
bool tone_source_available(const SourceAsset& s,std::stop_token stop){try{CabManifest m;m.root=path(s.root);CabAsset a;a.relative=s.file.relative;a.digest=s.file.digest;a.bytes=s.file.bytes;const auto matches=[&]{try{const auto info=inspect_wav(m.root/path(a.relative));return info.sample_rate==s.rate&&info.channels==s.channels&&static_cast<std::uint64_t>(info.frame_count)==s.frames&&verify_cab_asset(m,a,stop);}catch(const std::exception&){return false;}};if(matches())return true;const auto absolute=path(s.file.absolute);m.root=absolute.parent_path();a.relative=utf8(absolute.filename());return matches();}catch(const std::exception&){return false;}}
ReverbState tone_source_state(const SourceAsset& s,std::string name){ReverbState r;r.name=std::move(name);r.first=s.file;r.sample_rate=s.rate;r.channels=s.channels;r.frames=s.frames;r.validate();return r;}
void relink_tone_source(SourceAsset& source,const CabManifest& m,const CabAsset& a){require(a.present&&a.error.empty()&&a.digest==source.file.digest&&a.bytes==source.file.bytes&&a.rate==source.rate&&a.frames==source.frames&&a.channels==source.channels,"Relink requires the exact original source content");const auto id=source.id;source=asset(m,a);source.id=id;}
}
